#define OFF_BIPOBJ_ADDON      0x18          /* BIPOBJECT::armorAddon */
#define OFF_BIPOBJ_CLONE      0x30          /* BIPOBJECT::partClone */
#define BIKE_SLOT_INDEX       27            /* biped slot 57 (slots start at 30) */
#define OFF_CAMERA_STATE      0x28          /* TESCamera::cameraState (the current one) */
#define OFF_CAMERA_STATES     0xE0          /* PlayerCamera::cameraStates[] */
#define CAMERA_THIRD_PERSON1  7             /* kCameraState_ThirdPerson1, ThirdPerson2 */

/* --- Our side --- */
#define ESP_NAME              "CommonwealthMotorbike.esp"
#define SLOPE_GLOBAL_ID       0x82Au        /* CMB_SlopeLive, set by CMB_ControllerScript */
#define SLOPE_GLOBAL_EDITOR_ID "CMB_SlopeLive"
#define CAMERA_GLOBAL_ID      0x82Bu        /* CMB_CameraLive, likewise */
#define CAMERA_GLOBAL_EDITOR_ID "CMB_CameraLive"
#define CAMERA_SETTING        "fVanityModeMaxDist:Camera"
#define TILT_GLOBAL_ID        0x82Cu        /* CMB_TiltLive, set by CMB_ControllerScript */
#define TILT_GLOBAL_EDITOR_ID "CMB_TiltLive"
#define GROUND_GLOBAL_ID      0x82Du        /* CMB_GroundNormalX, Y, Z: 82D, 82E, 82F (we write these) */
#define PARK_GLOBAL_ID        0x831u        /* CMB_ParkX, Y, Z, Angle, UpX, UpY, UpZ: 831-837 (we write these) */
#define SLOPE_TRACK_GLOBAL_ID 0x838u        /* CMB_TrackSlope (we write it) */
#define TURN_RADIUS_GLOBAL_ID 0x839u        /* CMB_TurnRadius (MCM): the tightest turn while riding, 0 = off */
#define TURN_STAND_GLOBAL_ID  0x83Au        /* CMB_StandTurnRate (MCM): degrees a second when stopped */
#define TURN_SLOW_GLOBAL_ID   0x83Bu        /* CMB_TurnRadiusSlow (MCM): the tightest turn at walking pace */
#define HEADLAMP_GLOBAL_ID    0x83Du        /* CMB_HeadlampLive (CMB_ControllerScript): 1 while the headlamp should be lit */
#define HEADLAMP_REF_HI_ID    0x843u        /* CMB_HeadlampRefHi: the light reference the script placed, its form id's high 16 bits */
#define HEADLAMP_REF_LO_ID    0x844u        /* CMB_HeadlampRefLo: the low 16 bits (both 0: none) */
#define RAM_GLOBAL_ID         0x845u        /* CMB_RamSeenHi, SeenLo, Seen, Ok, HitSpeed, Hit, Enemies, MinSpeed: 845-84C (knocking enemies over, CMB_RamScript) */
#define RAM_GLOBALS           8
#define OFF_AV_USER_DATA      0x110         /* NiAVObject::userData: the reference whose 3D this is (CommonLibF4; F4SE 0.7.9's unk110) */
#define FORM_TYPE_ACHR        0x41          /* Actor */
#define FORM_TYPE_RACE        0x11          /* TESRace */
#define OFF_ACTOR_RACE        0x418         /* Actor::race (F4SE 0.7.9, CommonLibF4) */
#define OFF_RACE_FLAGS        0x1A0         /* TESRace::data (+0x180, F4SE's unk170 block and CommonLibF4's RACE_DATA) .flags (+0x20) */
#define OFF_RACE_SIZE         0x1AC         /* ... .raceSize (+0x2C): 0 small, 1 medium, 2 large, 3 extra large */
#define OFF_RACE_EDITOR_ID    0x3A0         /* TESRace::editorId (BSFixedString; both agree) */
#define RACE_PLAYABLE         0x1u
#define RACE_NO_KNOCKDOWNS    0x00400000u   /* RACE DATA flags (xEdit): 'No Knockdowns' */
#define RAM_MAX_ASK           8388607       /* the asks count 1 to 2^23 - 1, exact in a float, then from 1 again */
#define RAM_ROBOTS_ID         0x856u        /* CMB_RamRobots: a FormList of the races that pass the size and No Knockdowns gates (test 42's protectrons and eyebot) */
#define FORM_TYPE_FLST        0x5E          /* BGSListForm (CommonLibF4's ENUM_FORM_ID::kFLST) */
#define RTTI_FORM_LIST        ".?AVBGSListForm@@"
#define OFF_FLST_FORMS        0x20          /* BGSListForm::arrayOfForms, a BSTArray<TESForm *> right after TESForm (0x20; CommonLibF4) */
#define ROOM_GLOBAL_ID        0x84Fu        /* CMB_RoomAskX, AskY, AskZ, Ask (the script writes), Answer, Clear (we write): 84F-854 (the brought bike's spot, CMB_ControllerScript; test 41) */
#define ROOM_GLOBALS          6
#define ROOM_MORE_ID          0x86Du        /* CMB_RoomOptions, CMB_RoomPitch, CMB_RoomRoll, CMB_RoomGround: 86D-870 (test 46: the script's spots around the player and its call's fallback, the brought bike's tilt and ground), after the nine engine loops' descriptors so no ID moves */
#define ROOM_MORE_GLOBALS     4
#define SND_LOOPS             11            /* the engine's loops the script hands over (test 44's build): CMB_SndLoop01 to CMB_SndLoop11 */
#define SND_GLOBALS           (SND_LOOPS + 2)
#define SND_GLOBAL_ID         0x857u        /* CMB_SndLoop01-11 857-861 (the loops' instance ids, the script writes), CMB_SndGen 862 (the script bumps it after them), CMB_SndDriven 863 (we write it) */
#define ENGINE_VOLUME_GLOBAL_ID 0x81Cu      /* CMB_EngineVolume (the MCM's engine volume, 0 to 100): since test 46 this plugin puts it on the loops it drives */
/* The 2026-11-01a build's globals, 0x872-0x878, right after the engine's output model 0x871 (Program.cs's fixed-ID
 * block; fake_game.c's FORMIDs): found by ID in FindGlobals, one line for the seven. */
#define TAIL_REF_HI_ID        0x872u        /* CMB_TailRefHi: the tail lamp's light reference the script placed, its form id's high 16 bits */
#define TAIL_REF_LO_ID        0x873u        /* CMB_TailRefLo: the low 16 bits (both 0: none) */
#define VIEW_REF_HI_ID        0x874u        /* CMB_ViewRefHi: the first-person bike's reference (CMB_BikeView), high 16 bits */
#define VIEW_REF_LO_ID        0x875u        /* CMB_ViewRefLo: the low 16 bits (both 0: none) */
#define ROOM_KIND_ID          0x876u        /* CMB_RoomAskKind (the script writes it with each room ask): 1 = the ask is a navmesh point, 0 a spot */
#define RIDER_POSE_OFF_ID     0x877u        /* CMB_RiderPoseOff (we write it, the controller reads it): the raw seconds the rider's clips have been off the seat, 0 while seated and at a ride's start and end; the script compares it with its CMB_PoseOffAfter (3.0) */
#define BRAKE_KEY_GLOBAL_ID   0x878u        /* CMB_BrakeKey (the MCM's "Brake key"): a DirectInput scan code, 57 = Space, 0 none */
/* The bike's own sounds besides the engine (2026-11-01a, fxsound), 0x884-0x88A right after the build's other forms
 * (Program.cs's fixed IDs; fake_game.c's FX_FORMID): found by ID in FindGlobals, all seven or none, one line. */
#define FX_GLOBAL_ID          0x884u        /* CMB_FxVolume, the first of the seven */
#define FX_GLOBALS            7
#define FX_VOLUME             0             /* CMB_FxVolume 884 (the MCM's "Bike effects volume", 0 to 100, 90; 0 none): read every frame for the water loop */
#define FX_WATER_ID           1             /* CMB_FxWaterId 885 (the script writes it): the water loop's instance id, played at no volume on getting on; 0 none */
#define FX_DRIVEN             2             /* CMB_FxDriven 886 (we write it): the id when we drive that loop, minus it when we decline it */
#define FX_AIR                3             /* CMB_FxAir 887 (we write it): 0 on the ground, 1 once [Fx] AirMin (0.35 s) in the air, 2 for AirHold (0.3 s) after that flight's landing */
#define FX_LAND_SEQ           4             /* CMB_FxLandSeq 888 (we write it): one more at each take-off past AirMin, started from its own value each ride */
#define FX_LAND_LEVEL         5             /* CMB_FxLandLevel 889 (we write it): the landing's level 0-1 from the fall's speed, +2 into water; -1 (the ESP's, and Land=0): no cue */
#define FX_LAND_PLAYED        6             /* CMB_FxLandPlayed 88A (the script writes it): the flight whose landing sound it played last */
/* The 2026-11-02a build's three (test 48's answer), 0x893-0x895 right after the bike sounds' lists (Program.cs's fixed
 * IDs; fake_game.c's ITEM_USE_FORMID, RAM_COMBAT_FORMID and FX_RANGE_FORMID): found by ID in FindGlobals, all three or
 * none, one line. */
#define RIDER_ITEM_USE_ID     0x893u        /* CMB_RiderItemUse (the script writes it): a count of the items used while riding, 1-999 then 1 again, at the use or the menu's close */
#define RAM_COMBAT_ID         0x894u        /* CMB_RamCombat (the controller writes it, CombatHint every tick): 1 while the player is in combat */
#define FX_RANGE_ID           0x895u        /* CMB_FxLandRange (the MCM's "Landing loudness range (dB)", 0-30): 10; 18 = 2026-11-01a */
/* The 2026-11-06a build's five (test 49's answer), 0x8B0-0x8B4 (0x8AF is kept for CMB_LookCode; Program.cs's fixed IDs;
 * fake_game.c's VIEW_TIP_FORMID .. FX_WATER_LOOP_FORMID): found by ID in FindGlobals, all five or none, one line. */
#define VIEW_TIP_ID           0x8B0u        /* CMB_ViewTip (the MCM's "Look down on getting into first person (deg)", 0-45): 20; 0 = 2026-11-02a */
#define VIEW_FOV_ID           0x8B1u        /* CMB_ViewFov (the MCM's "Field of view riding in first person", 0-120): 0 = the game's own (2026-11-02a) */
